import { createSlice, PayloadAction } from "@reduxjs/toolkit";

interface Unit {
    id: number,
    imei: string,
    patente: string,
    tipo_de_unidad: string,
    estado: string,
    condicion: string,
    lock_id: string,
    created_at: string,
    updated_at: string
}

interface UnitState {
    units: Unit[],
    paginate: {
        current: number,
        pageSize: number,
        hasNextPage: boolean,
        hasPreviousPage: boolean,
        total: number,
        totalPages: number
    } | null,
    activeUnit: Unit | null,
    errorMessage: string | null
}


const initialState: UnitState  = {
    units: [],
    paginate: null,
    activeUnit: null,
    errorMessage: null
}

const unitCatalogSlice = createSlice({
    name: "unitsCatalog",
    initialState,
    reducers: {
        handleUnits(state: UnitState, action: PayloadAction<any>) {
            const { items, ...pagination } = action.payload
            state.units = items
            state.paginate = { ...pagination }
            state.activeUnit = null
        },
        handleSearchUnit(state: UnitState, action: PayloadAction<any>) {
            state.units = action.payload
        },
        setActiveUnit(state: UnitState, action: PayloadAction<number>) {
            state.activeUnit = state.units.find((unit) => unit.id === action.payload) || null
        },
        resetActiveUnit(state: UnitState) {
            state.activeUnit = null
        },
    },
});

export const { 
    handleUnits, 
    handleSearchUnit,
    setActiveUnit,
    resetActiveUnit,
} = unitCatalogSlice.actions;

export default unitCatalogSlice.reducer;
